const allRows = $input.all();
const now = new Date();
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
const weekRows = allRows.filter(item => {
  const row = item.json;
  if (!row.abandoned_at) return false;
  const abandonedDate = new Date(row.abandoned_at);
  return abandonedDate >= oneWeekAgo && abandonedDate <= now;
});
const totalAbandoned = weekRows.length;
const totalRecovered = weekRows.filter(r => r.json.recovered === 'TRUE').length;
const recoveryRate = totalAbandoned > 0 ? ((totalRecovered / totalAbandoned) * 100).toFixed(1) : 0;
const totalRevenueLost = weekRows.reduce((sum, r) => sum + parseFloat(r.json.cart_total || 0), 0);
const totalRevenueRecovered = weekRows.filter(r => r.json.recovered === 'TRUE').reduce((sum, r) => sum + parseFloat(r.json.recovery_revenue || 0), 0);
const email1Count = weekRows.filter(r => r.json.email1_sent === 'TRUE').length;
const email2Count = weekRows.filter(r => r.json.email2_sent === 'TRUE').length;
const email3Count = weekRows.filter(r => r.json.email3_sent === 'TRUE').length;
const recoveredViaEmail1 = weekRows.filter(r => r.json.recovered === 'TRUE' && r.json.recovered_via === 'email1_reminder').length;
const recoveredViaEmail2 = weekRows.filter(r => r.json.recovered === 'TRUE' && r.json.recovered_via === 'email2_urgency').length;
const recoveredViaEmail3 = weekRows.filter(r => r.json.recovered === 'TRUE' && r.json.recovered_via === 'email3_discount').length;
let bestEmail = 'None';
const maxRecoveries = Math.max(recoveredViaEmail1, recoveredViaEmail2, recoveredViaEmail3);
if (maxRecoveries > 0) {
  if (maxRecoveries === recoveredViaEmail1) bestEmail = 'Email 1 (Reminder)';
  else if (maxRecoveries === recoveredViaEmail2) bestEmail = 'Email 2 (Urgency)';
  else bestEmail = 'Email 3 (Discount)';
}
const weekStart = oneWeekAgo.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const weekEnd = now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
return [{ json: { week_range: `${weekStart} – ${weekEnd}`, total_abandoned: totalAbandoned, total_recovered: totalRecovered, recovery_rate: recoveryRate, total_revenue_at_risk: totalRevenueLost.toFixed(2), total_revenue_recovered: totalRevenueRecovered.toFixed(2), email1_sent: email1Count, email2_sent: email2Count, email3_sent: email3Count, total_emails_sent: email1Count + email2Count + email3Count, recovered_via_email1: recoveredViaEmail1, recovered_via_email2: recoveredViaEmail2, recovered_via_email3: recoveredViaEmail3, best_performing_email: bestEmail } }];

const body = $input.first().json.body;
const email = body.email || body.customer?.email || '';
const orderTotal = body.total_price || '0';
const orderId = body.id || '';
const orderName = body.name || '';
return [{ json: { order_email: email, order_total: orderTotal, order_id: orderId, order_name: orderName, paid_at: new Date().toISOString() } }];

const row = $input.first().json;
const orderData = $('Parse Order Information').first().json;
let recoveredVia = 'unknown';
if (row.email3_sent === 'TRUE') { recoveredVia = 'email3_discount'; }
else if (row.email2_sent === 'TRUE') { recoveredVia = 'email2_urgency'; }
else if (row.email1_sent === 'TRUE') { recoveredVia = 'email1_reminder'; }
return [{ json: { checkout_token: row.checkout_token, customer_email: row.customer_email, customer_name: row.customer_name, original_cart_total: row.cart_total, recovery_revenue: orderData.order_total, recovered_via: recoveredVia, recovered_at: new Date().toISOString(), order_id: orderData.order_id, order_name: orderData.order_name } }];

const results = $input.all();
if (!results || results.length === 0) {
  return [{ json: { is_duplicate: false, reason: 'No existing sequence found' } }];
}
const activeSequence = results.find(item => {
  const row = item.json;
  return row.email3_sent === 'FALSE' && row.recovered === 'FALSE';
});
if (activeSequence) {
  return [{ json: { is_duplicate: true, reason: 'Active sequence already running', existing_token: activeSequence.json.checkout_token } }];
}
return [{ json: { is_duplicate: false, reason: 'Previous sequences completed' } }];

const body = $('Checkout Created Webhook Trigger').first().json.body;
const products = (body.line_items || []).map(item => `${item.title} x${item.quantity}`).join(', ');
const firstName = body.customer?.first_name || body.billing_address?.first_name || 'there';
return [{ json: { checkout_token: body.token, customer_email: body.email, customer_name: firstName, cart_total: body.total_price, currency: body.currency || 'USD', products: products, abandoned_checkout_url: body.abandoned_checkout_url, shop_domain: body.domain || 'YOUR_SHOP.myshopify.com', abandoned_at: new Date().toISOString(), item_count: (body.line_items || []).length } }];

const customerName = $('Extract Checkout Cart Data').item.json.customer_name;
const nameSlug = customerName.toUpperCase().replace(/[^A-Z]/g, '').slice(0, 4);
const random = Math.random().toString(36).substring(2, 7).toUpperCase();
const discountCode = `RECOVER-${nameSlug}-${random}`;
const expiresAt = new Date();
expiresAt.setHours(expiresAt.getHours() + 24);
return [{ json: { ...$('Extract Checkout Cart Data').item.json, discount_code: discountCode, discount_expires_at: expiresAt.toISOString(), discount_percent: 10 } }];
